-- ── story 1-1: per-client SKU identity ────────────────────────────────────
-- Generated by drizzle-kit (the index swap, the new code index, the GRN
-- column) and hand-amended below the marker: the GRN client backfill, its
-- notice, and the post-migration probes (drizzle-kit is blind to all of them;
-- `bun run db:generate` afterwards reports "No schema changes").
--
-- SKU code and barcode become unique per (tenant, client) instead of per
-- tenant: two client brands may both own `TSHIRT-M` and both sell one GTIN.
-- NO SKU DATA CHANGES — every existing row already satisfies the looser rule
-- (unique per tenant implies unique per (tenant, client)).
--
-- Cost: each index build takes a SHARE lock on `skus` for its duration, inside
-- the migrator's single transaction (writes to `skus` wait; reads do not) —
-- acceptable for a catalog-sized table.
--
-- Rollback: recreating the per-tenant indexes is IMPOSSIBLE once any two
-- clients hold the same code or barcode; there is no automatic down
-- migration. A rollback must first rename every cross-client duplicate.
--
-- `goods_receipt_notes.client_id` is a new NULLABLE column with no CHECK:
-- older blind receipts could mix clients, so history cannot satisfy one. The
-- receiving command stamps every new row. Older rows are backfilled below
-- from their lines' SKUs where those lines name exactly one client; mixed or
-- line-less older rows stay null and are listed by the notice.
DROP INDEX "skus_tenant_id_code_unique";--> statement-breakpoint
DROP INDEX "skus_tenant_id_barcode_unique";--> statement-breakpoint
ALTER TABLE "goods_receipt_notes" ADD COLUMN "client_id" uuid;--> statement-breakpoint
CREATE UNIQUE INDEX "skus_tenant_client_code_unique" ON "skus" USING btree ("tenant_id","client_id","code");--> statement-breakpoint
CREATE UNIQUE INDEX "skus_tenant_client_barcode_unique" ON "skus" USING btree ("tenant_id","client_id","barcode");--> statement-breakpoint
CREATE INDEX "skus_tenant_code_idx" ON "skus" USING btree ("tenant_id","code");--> statement-breakpoint
-- ── hand-amended: the GRN client backfill ─────────────────────────────────
-- Fail-fast: the column was added by THIS migration, so a stamped row before
-- the backfill means it already ran (IMPLEMENTATION-GUIDE §3).
DO $$
BEGIN
	IF EXISTS (SELECT 1 FROM "goods_receipt_notes" WHERE "client_id" IS NOT NULL) THEN
		RAISE EXCEPTION 'migration 0076: goods_receipt_notes.client_id is already stamped — the backfill has run.';
	END IF;
END $$;
--> statement-breakpoint
UPDATE "goods_receipt_notes" g
SET "client_id" = one."client_id"
FROM (
	SELECT l."tenant_id", l."grn_id", min(s."client_id"::text)::uuid AS "client_id"
	FROM "goods_receipt_lines" l
	JOIN "skus" s ON s."tenant_id" = l."tenant_id" AND s."id" = l."sku_id"
	GROUP BY l."tenant_id", l."grn_id"
	HAVING count(DISTINCT s."client_id") = 1
) one
WHERE g."tenant_id" = one."tenant_id" AND g."id" = one."grn_id";
--> statement-breakpoint
-- ── hand-amended: the notice — every older GRN left without a client ──────
-- Mixed-client or line-less receipts stay null (no CHECK; nothing reads the
-- column as required). Listed once so an operator can see them; never fatal.
DO $$
DECLARE
	left_null bigint;
	sample text;
BEGIN
	SELECT count(*) INTO left_null FROM "goods_receipt_notes" WHERE "client_id" IS NULL;
	IF left_null > 0 THEN
		SELECT string_agg(format('%s (tenant %s, %s)', "code", "tenant_id", "id"), '; ' ORDER BY "tenant_id", "code")
		INTO sample
		FROM (
			SELECT "code", "tenant_id", "id" FROM "goods_receipt_notes"
			WHERE "client_id" IS NULL
			ORDER BY "tenant_id", "code"
			LIMIT 200
		) n;
		RAISE NOTICE 'migration 0076: % goods receipt(s) left without a client (mixed-client or line-less history; first 200): %', left_null, sample;
	END IF;
END $$;
--> statement-breakpoint
-- ── the post-migration assertion: the swapped indexes (the 0064 model) ─────
-- Made-up uuids; the accepted shape (two clients holding one code and one
-- barcode) is inserted first and rolled back by a sentinel exception, so an
-- index that still refused across clients fails the migration. Each refused
-- shape runs in its own subtransaction and must be refused by unique_violation
-- ON THE NAMED INDEX.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	client_a uuid := gen_random_uuid();
	client_b uuid := gen_random_uuid();
	refused_by text;
	probe text;
	expected text;
BEGIN
	-- (1) the accepted shape: two clients, the same code and the same barcode.
	BEGIN
		INSERT INTO "skus" ("id","tenant_id","client_id","code","name","uom","gst_rate_bps","barcode")
		VALUES (gen_random_uuid(), t, client_a, 'P-0076-CODE', 'probe a', 'each', 0, 'P-0076-GTIN'),
		       (gen_random_uuid(), t, client_b, 'P-0076-CODE', 'probe b', 'each', 0, 'P-0076-GTIN');
		RAISE EXCEPTION USING ERRCODE = 'P0076', MESSAGE = 'rollback the accepted probes';
	EXCEPTION WHEN SQLSTATE 'P0076' THEN NULL;
	END;
	-- (2) the refused shapes: one client's duplicate, under each index.
	FOREACH probe IN ARRAY ARRAY['one client: duplicate code', 'one client: duplicate barcode'] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'one client: duplicate code' THEN 'skus_tenant_client_code_unique'
			ELSE 'skus_tenant_client_barcode_unique'
		END;
		BEGIN
			CASE probe
				WHEN 'one client: duplicate code' THEN
					INSERT INTO "skus" ("id","tenant_id","client_id","code","name","uom","gst_rate_bps","barcode")
					VALUES (gen_random_uuid(), t, client_a, 'P-0076-CODE', 'probe a', 'each', 0, 'P-0076-GTIN-1'),
					       (gen_random_uuid(), t, client_a, 'P-0076-CODE', 'probe a2', 'each', 0, 'P-0076-GTIN-2');
				WHEN 'one client: duplicate barcode' THEN
					INSERT INTO "skus" ("id","tenant_id","client_id","code","name","uom","gst_rate_bps","barcode")
					VALUES (gen_random_uuid(), t, client_a, 'P-0076-CODE-1', 'probe a', 'each', 0, 'P-0076-GTIN'),
					       (gen_random_uuid(), t, client_a, 'P-0076-CODE-2', 'probe a2', 'each', 0, 'P-0076-GTIN');
			END CASE;
		EXCEPTION WHEN unique_violation THEN
			GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS NULL THEN
			RAISE EXCEPTION 'migration 0076: the probe "%" was not refused.', probe;
		END IF;
		IF refused_by <> expected THEN
			RAISE EXCEPTION 'migration 0076: the probe "%" was refused by % — expected %.', probe, refused_by, expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "skus" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0076: a probe row survived.';
	END IF;
END $$;
